use crate::resample::{crop_rgb8,resize_rgb8};
use crate::types::RoiRect;
#[derive(Clone,Debug)] pub struct ImageView{pub width:usize,pub height:usize,pub rgb:Vec<u8>,pub source_roi:Option<RoiRect>}
pub fn context_and_roi_views(src:&[u8],width:usize,height:usize,rois:&[RoiRect],context_scale:f32,roi_max_side:usize)->Vec<ImageView>{if width==0||height==0||src.len()<width*height*3{return Vec::new();}let scale=context_scale.clamp(0.02,1.0);let cw=((width as f32*scale).round() as usize).max(1);let ch=((height as f32*scale).round() as usize).max(1);let mut views=Vec::with_capacity(rois.len()+1);views.push(ImageView{width:cw,height:ch,rgb:resize_rgb8(src,width,height,cw,ch),source_roi:None});for &roi in rois{let r=roi.normalized();let x0=(r.x*width as f32).floor() as usize;let y0=(r.y*height as f32).floor() as usize;let x1=((r.x+r.w)*width as f32).ceil() as usize;let y1=((r.y+r.h)*height as f32).ceil() as usize;let(crop,rw,rh)=crop_rgb8(src,width,height,x0,y0,x1,y1);if rw==0||rh==0{continue;}let max_side=roi_max_side.max(1);let rs=(max_side as f32/rw.max(rh) as f32).min(1.0);let ow=((rw as f32*rs).round() as usize).max(1);let oh=((rh as f32*rs).round() as usize).max(1);views.push(ImageView{width:ow,height:oh,rgb:resize_rgb8(&crop,rw,rh,ow,oh),source_roi:Some(r)});}views}
